<pre><code>jest.unmock('./utils.js');
//jest.setTimeout(10000);
describe('test', () =&gt; {
     it('test', async () =&gt; {
        await expect(getAPISecretKey('testKey')).rejects.toThrow('AKV10000: Request is missing a Bearer or PoP token.');

     });
 });
</code></pre>

